#!/usr/bin/env node
// Photos' Import review on the desktop served by `ferrite dev`: File > Import… shows the chosen
// files before anything is added, leaves out what the library already holds, imports only what is
// chosen, and Cancel adds nothing. Exits 0 only with every step passed and no console or HTTP
// error. Pictures are JPEGs generated by the journey's page. It deletes only what it made.
//
//   node e2e/photos-import-journey.mjs [--url http://127.0.0.1:8787] [--out <dir>] [--browser ...]

import path from "node:path";
import { api, journey, openDesktop, options, shot } from "./app-journey.mjs";

const { base, out } = options();
const { step, run } = journey("photos-import");
const tag = Date.now().toString(36);
const NAMES = ["Left", "Middle", "Right"].map((word) => `${word} ${tag}`);
const library = async (page) => (await api(page, "GET", "/api/photos/library")).json;

async function until(check, ms = 15_000) {
  const end = Date.now() + ms;
  for (;;) {
    const value = await check();
    if (value) return value;
    if (Date.now() > end) return value;
    await new Promise((resolve) => setTimeout(resolve, 150));
  }
}

const ours = async (page) =>
  ((await library(page)).photos ?? []).filter((photo) => NAMES.includes(photo.name));

await run(async (page) => {
  await openDesktop(page, base, step);
  const pictures = await page.evaluate(async (names) => {
    const made = [];
    for (const [at, name] of names.entries()) {
      const canvas = document.createElement("canvas");
      canvas.width = 240;
      canvas.height = 180;
      const context = canvas.getContext("2d");
      context.fillStyle = `hsl(${at * 120} 70% 50%)`;
      context.fillRect(0, 0, 240, 180);
      made.push({ name: `${name}.jpg`, url: canvas.toDataURL("image/jpeg", 0.9) });
    }
    return made;
  }, NAMES);
  const files = pictures.map(({ name, url }) => ({
    name,
    mimeType: "image/jpeg",
    buffer: Buffer.from(url.split(",")[1], "base64"),
  }));

  await page.getByRole("menuitem", { name: "Spotlight" }).click();
  const field = page.getByRole("combobox", { name: "Spotlight Search" });
  await field.fill("Photos");
  await field.press("Enter");
  const win = page.locator(".mac-window:has(.mac-photos-body)").first();
  await win.waitFor({ timeout: 10_000 });
  await until(async () => !(await win.getAttribute("aria-busy")));

  const review = async (chosen) => {
    await page.getByRole("menuitem", { name: "File", exact: true }).click();
    const choosing = page.waitForEvent("filechooser", { timeout: 10_000 });
    await page.getByRole("menuitem", { name: "Import…", exact: true }).click();
    await (await choosing).setFiles(chosen);
    await page.getByRole("button", { name: "Import All New Items" }).waitFor({ timeout: 5_000 });
  };
  const item = (name) => page.locator(".mac-photos-import-item", { hasText: `${name}.jpg` });

  await review(files);
  step(
    "Import shows a tile per chosen file",
    (await page.locator(".mac-photos-import-item").count()) === 3,
  );
  await page.getByRole("button", { name: "Cancel", exact: true }).click();
  await page.waitForTimeout(500);
  step("Cancel adds nothing", (await ours(page)).length === 0);

  await review(files);
  await item(NAMES[1]).click();
  await item(NAMES[2]).click();
  await page.waitForTimeout(200);
  await shot(page, path.join(out, "photos-import-review.png"));
  await page.getByRole("button", { name: "Import 1 Selected" }).click();
  await until(async () => (await ours(page)).length === 1);
  step("Import 1 Selected imports the one chosen", (await ours(page))[0]?.name === NAMES[0]);

  await review(files);
  step(
    "a file the library holds starts unchosen and is marked",
    (await item(NAMES[0]).getAttribute("aria-pressed")) === "false" &&
      (await item(NAMES[0]).getAttribute("data-held")) === "",
  );
  await page.getByRole("button", { name: "Import All New Items" }).click();
  await until(async () => (await ours(page)).length === 3);
  step(
    "Import All New Items imports the rest, with no second copy",
    (await ours(page)).length === 3,
  );

  for (const photo of await ours(page)) {
    await api(page, "DELETE", `/api/photos/photos/${photo.id}`);
  }
});
